System.Assert.areEqual('same', 'same');
System.Assert.areNotEqual('left', 'right');
System.Assert.isFalse(false);
System.Assert.isNotNull('value');
System.Assert.isNull(null);
System.Assert.isTrue(true);
if (false) { System.Assert.fail(); }
if (false) { System.Assert.fail('message'); }
Exception emptyException = new AssertException();
Exception exceptionOnly = new AssertException(new DmlException('cause only'));
Exception stringOnly = new AssertException('message only');
Exception stringAndCause = new AssertException('message and cause', new DmlException('cause'));
System.assertEquals('System.AssertException', emptyException.getTypeName());
System.assertEquals('System.AssertException', exceptionOnly.getTypeName());
System.assertEquals('message only', stringOnly.getMessage());
System.assertEquals('message and cause', stringAndCause.getMessage());
if (false) { new AssertException('assert message').getInaccessibleFields(); }
Exception assertException = new AssertException('assert message');
System.assertEquals(null, assertException.getCause());
System.assertEquals('System.AssertException', assertException.getTypeName());
assertException.setMessage('changed assert');
System.assertEquals('changed assert', assertException.getMessage());
assertException.initCause(new DmlException('assert cause'));

